"""Airwindows' plug-ins as audio nodes, one class per plug-in.

Ported from Chris Johnson's Airwindows (https://github.com/airwindows/
airwindows, MIT). Every parameter is the plug-in's own 0..1 knob under its
own name, so Airwindows' descriptions of what a knob does hold here too::

    verb = audioairwindows.Galactic(sample_rate=48000, replace=0.6,
                                    bigness=0.8, dry_wet=0.4)
    verb.play(source)
    audio_out.play(verb)

Each node takes `sample_rate` and `channel_count` (1 or 2) at construction,
and `set()` changes any parameter while it plays, from the next block.

The nodes are audiodsp audio samples: they play any audiocore source and
anything that plays an audiocore sample plays them.
"""

from audiocore import (
    GET_BUFFER_DONE, GET_BUFFER_ERROR, GET_BUFFER_MORE_DATA, _AudioSample,
    get_buffer,
)
import _audioairwindows


__version__ = _audioairwindows.__version__
__revision__ = _audioairwindows.__revision__

FRAMES = _audioairwindows.FRAMES
FAST = bool(_audioairwindows.FAST_DEFAULT)
TUNED = bool(_audioairwindows.TUNED_DEFAULT)

_FIXED = ("sample_rate", "channel_count")


class _Airwindows(_AudioSample):
    _NAME = None
    _PARAMS = ()
    _NAMES = ()
    _DEFAULTS = ()

    def __init__(self, sample_rate=48000, channel_count=2, **options):
        channel_count = int(channel_count)
        if channel_count not in (1, 2):
            raise ValueError("channel_count must be 1 or 2")
        self._check_names(options)
        self.sample_rate = int(sample_rate)
        self.bits_per_sample = 16
        self.channel_count = channel_count
        self.samples_signed = True
        self.single_buffer = False
        self.max_buffer_length = FRAMES * 2 * channel_count
        self._deinited = False
        self._source = None
        self._pending = b""
        self._source_done = False
        self._state = _audioairwindows.State(
            self._NAME, sample_rate=self.sample_rate,
            channel_count=channel_count)
        self._values = list(self._DEFAULTS)
        self._apply(options)

    def _check_names(self, options):
        for name in options:
            if name not in self._PARAMS:
                raise TypeError("unknown %s option %r"
                                % (type(self).__name__, name))

    def _apply(self, options):
        for name, value in options.items():
            index = self._PARAMS.index(name)
            value = min(1.0, max(0.0, float(value)))
            self._state.configure(index, value)
            self._values[index] = value

    def parameters(self):
        """Each parameter's keyword, upstream's display name and its
        default, in upstream's order: what a screen needs to draw the
        knobs."""
        self._check()
        return tuple(zip(self._PARAMS, self._NAMES, self._DEFAULTS))

    def get(self, name):
        """One knob where it is now, 0..1."""
        self._check()
        if name not in self._PARAMS:
            raise KeyError("unknown %s option %r" % (type(self).__name__, name))
        return self._values[self._PARAMS.index(name)]

    def set(self, **options):
        """Change parameters while playing; each takes effect from the next
        block. `sample_rate` and `channel_count` are fixed at construction."""
        self._check()
        for name in _FIXED:
            if name in options:
                raise TypeError("%r is fixed at construction" % (name,))
        self._check_names(options)
        self._apply(options)

    def clear(self):
        """Empty every line and filter, as a newly built node's are."""
        self._check()
        self._state.reset()

    @property
    def playing(self):
        return self._source is not None

    def play(self, sample, *, loop=False):
        self._check()
        self._source = sample
        self._pending = b""
        self._source_done = False

    def stop(self):
        self._source = None
        self._pending = b""
        self._source_done = False

    def _release(self):
        self.stop()
        self._state = None

    def _reset_buffer(self, single_channel_output=False, audio_channel=0):
        self._check()
        # A host reset clears what this node holds of its own and keeps the
        # source frames it has already taken.
        self._state.reset()

    def _get_buffer(self, single_channel_output=False, audio_channel=0):
        self._check()
        output = bytearray()
        produced = 0
        width = 2 * self.channel_count
        while produced < FRAMES:
            if not self._pending:
                if self._source_done:
                    self._source = None
                    self._source_done = False
                if self._source is None:
                    break
                result, data = get_buffer(self._source, False, 0)
                data = bytes(data)
                if result == GET_BUFFER_ERROR or len(data) < width:
                    if result == GET_BUFFER_DONE:
                        self._source = None
                    break
                self._pending = data[:len(data) // width * width]
                self._source_done = result == GET_BUFFER_DONE
            run = min(FRAMES - produced, len(self._pending) // width)
            output += self._state.process(self._pending[:run * width])
            self._pending = self._pending[run * width:]
            produced += run
        # Whatever the source did not fill is rendered from silence, so the
        # block is always full and a reverb's tail rings out after its source
        # ends. A node in the middle of a live graph never reports itself
        # finished.
        if produced < FRAMES:
            output += self._state.process_silence(FRAMES - produced)
        return GET_BUFFER_MORE_DATA, self._publish(output)




